pragma solidity ^0.8.36;

contract LoopAssembly {
    function readOnly(uint256 n) external pure returns (uint256 total) {
        for (uint256 i = 0; i < n; i++) {
            assembly { total := add(total, i) }
        }
    }

    function writesCounter(uint256 n) external pure returns (uint256 total) {
        for (uint256 i = 0; i < n; i++) {
            assembly { i := add(i, 1) total := add(total, i) }
        }
    }
}

contract StorageBase {
    uint256 internal baseMarker;
}

contract NearEnd is StorageBase layout at 2**256 - 3 {
    uint256 internal marker;
}

contract EmptyNearEnd layout at 2**256 - 1 {}
